package edu.bis701.exp08;
import java.io.IOException;import org.apache.hadoop.conf.Configuration;import org.apache.hadoop.fs.Path;import org.apache.hadoop.io.*;import org.apache.hadoop.mapreduce.*;import org.apache.hadoop.mapreduce.lib.input.FileInputFormat;import org.apache.hadoop.mapreduce.lib.output.FileOutputFormat;
public class HadoopWordCount{public static class Tokenizer extends Mapper<LongWritable,Text,Text,IntWritable>{private final Text word=new Text();private static final IntWritable ONE=new IntWritable(1);protected void map(LongWritable k,Text v,Context c)throws IOException,InterruptedException{for(String token:v.toString().toLowerCase().split("\\W+")){if(!token.isEmpty()){word.set(token);c.write(word,ONE);}}}}public static class Sum extends Reducer<Text,IntWritable,Text,IntWritable>{protected void reduce(Text k,Iterable<IntWritable>vs,Context c)throws IOException,InterruptedException{int n=0;for(IntWritable v:vs)n+=v.get();c.write(k,new IntWritable(n));}}public static void main(String[]a)throws Exception{if(a.length!=2)throw new IllegalArgumentException("HadoopWordCount <input> <output>");Job j=Job.getInstance(new Configuration(),"BIS701 WordCount");j.setJarByClass(HadoopWordCount.class);j.setMapperClass(Tokenizer.class);j.setCombinerClass(Sum.class);j.setReducerClass(Sum.class);j.setOutputKeyClass(Text.class);j.setOutputValueClass(IntWritable.class);FileInputFormat.addInputPath(j,new Path(a[0]));FileOutputFormat.setOutputPath(j,new Path(a[1]));System.exit(j.waitForCompletion(true)?0:1);}}
